--- FILE: ./src/agent/index.ts ---
Range: 1 - 219

1 | /**
2 |  * Agent - AI 代理
3 |  * 负责编排 LLM 调用和会话管理
4 |  *
5 |  * 注意：此文件是旧版 Agent，建议使用 index-eventbus.ts 以获得 EventBus 集成
6 |  * 要启用 EventBus 功能，请导入 './index-eventbus' 而不是此文件
7 |  */
8 | import EventEmitter from "events";
9 | import { LLMProvider, LLMResponse, Message, ToolCall, ToolSchema } from "../providers/base";
10 | import { ScopedLogger } from "../util/log";
11 | import { SessionManager } from "../session-v2";
12 | import { ToolRegistry } from "../tool/registry";
13 | 
14 | export interface AgentConfig {
15 |     llmProvider: LLMProvider;
16 |     sessionManager: SessionManager;
17 |     systemPrompt: string;
18 |     /** 默认工具列表（可选），不传则使用 ToolRegistry 中所有工具 */
19 |     defaultTools?: ToolSchema[];
20 |     /** 最大循环次数，防止无限循环，默认 1024 */
21 |     maxLoop?: number;
22 |     /** 最大 token 数，默认 8000 */
23 |     maxTokens?: number;
24 |     /** 最大输出 token 数，默认 8000 */
25 |     maxOutputTokens?: number;
26 |     /** 工具并发上限，默认 1 */
27 |     toolConcurrency?: number;
28 |     /** 单次工具调用超时（毫秒），默认 300000 (5分钟) */
29 |     toolTimeoutMs?: number;
30 |     /** 连续错误次数上限，默认 2 */
31 |     noProgressLimit?: number;
32 | }
33 | 
34 | export interface AgentResponse {
35 |     content: string;
36 |     role: Message['role'];
37 |     type?: Message['type'];
38 | }
39 | 
40 | export default class Agent extends EventEmitter {
41 |     private llmProvider: LLMProvider;
42 |     private logger: ScopedLogger;
43 |     private sessionManager: SessionManager;
44 |     private systemPrompt: string;
45 |     private defaultTools: ToolSchema[] | undefined;
46 |     private maxLoop: number;
47 |     maxOutputTokens: number;
48 |     maxTokens: number;
49 |     private noProgressLimit: number;
50 | 
51 |     constructor(config: AgentConfig) {
52 |         super();
53 |         this.llmProvider = config.llmProvider;
54 |         this.sessionManager = config.sessionManager;
55 |         this.systemPrompt = config.systemPrompt;
56 |         this.defaultTools = config.defaultTools;
57 |         this.logger = new ScopedLogger('Agent');
58 |         this.maxLoop = config.maxLoop ?? 1024;
59 | 
60 |         const providerMaxOutput = this.llmProvider.maxOutputTokens;
61 |         const providerMaxTokens = this.llmProvider.maxTokens;
62 |         this.maxOutputTokens = Math.min(config.maxOutputTokens ?? providerMaxOutput, providerMaxOutput);
63 |         this.maxTokens = Math.min(config.maxTokens ?? providerMaxTokens, providerMaxTokens);
64 |         this.noProgressLimit = Math.max(0, config.noProgressLimit ?? 2);
65 | 
66 |         this.sessionManager.maxOutputTokens = this.maxOutputTokens;
67 |         this.sessionManager.maxTokens = this.maxTokens;
68 |     }
69 | 
70 |     /**
71 |      * 执行单个工具调用
72 |      */
73 |     private async executeToolCall(toolCall: ToolCall): Promise<Message> {
74 |         const { name, arguments: args } = toolCall.function;
75 |         if (!name) {
76 |             return {
77 |                 role: 'tool',
78 |                 type: 'text',
79 |                 content: 'Error: Tool name is empty',
80 |                 tool_call_id: toolCall.id,
81 |             };
82 |         }
83 | 
84 |         const result = await ToolRegistry.execute(name, args);
85 | 
86 |         let content: string;
87 |         if (typeof result === 'string') {
88 |             content = result;
89 |         } else {
90 |             content = JSON.stringify(result?.metadata ?? result ?? {});
91 |         }
92 | 
93 |         return {
94 |             role: 'tool',
95 |             type: 'text',
96 |             content,
97 |             tool_call_id: toolCall.id,
98 |         };
99 |     }
100 | 
101 |     /**
102 |      * 处理工具调用，返回是否有工具被调用
103 |      */
104 |     private async handleToolCalls(
105 |         llmResponse: LLMResponse,
106 |         spinner: ReturnType<ScopedLogger['spinner']>
107 |     ): Promise<boolean> {
108 |         if (!llmResponse.tool_calls || llmResponse.tool_calls.length === 0) {
109 |             return false;
110 |         }
111 | 
112 |         const toolResults = await Promise.all(
113 |             llmResponse.tool_calls.map(call => this.executeToolCall(call))
114 |         );
115 | 
116 |         this.sessionManager.addMessage(toolResults);
117 | 
118 |         // Bug修复：提取content字段进行拼接，而非直接join对象数组
119 |         const summaries = toolResults
120 |             .map(r => {
121 |                 const content = r.content ?? '';
122 |                 return content.length > 50 ? content.slice(0, 47) + '...' : content;
123 |             })
124 |             .join(', ');
125 | 
126 |         spinner.succeed(`Tool calls: ${summaries}`);
127 |         return true;
128 |     }
129 | 
130 |     /**
131 |      * 运行 Agent 处理用户查询
132 |      * @param query 用户查询
133 |      * @param options 选项
134 |      * @returns Agent 响应
135 |      */
136 |     async run(
137 |         query: string,
138 |         options?: { silent?: boolean; tools?: ToolSchema[] }
139 |     ): Promise<AgentResponse | null> {
140 |         const tools = options?.tools ?? this.defaultTools ?? [];
141 |         let consecutiveErrorCount = 0;
142 | 
143 |         // 添加用户消息
144 |         this.sessionManager.addMessage({
145 |             role: 'user',
146 |             type: 'text',
147 |             content: query,
148 |         });
149 | 
150 |         for (let i = 0; i < this.maxLoop; i++) {
151 |             const llmMessages = await this.sessionManager.getMessages();
152 |             const spinner = this.logger.spinner(`Thinking-${i + 1}...`);
153 | 
154 |             try {
155 |                 const llmResponse = await this.llmProvider.generate(
156 |                     [
157 |                         { role: 'system', content: this.systemPrompt },
158 |                         ...llmMessages,
159 |                     ],
160 |                     {
161 |                         model: process.env.AI_MODEL,
162 |                         tools: tools.length > 0 ? tools : undefined,
163 |                         max_tokens: this.maxOutputTokens,
164 |                     }
165 |                 );
166 | 
167 |                 if (!llmResponse) {
168 |                      throw new Error('LLM response is null');
169 |                 }
170 |                   
171 |                 this.sessionManager.addMessage(llmResponse);
172 | 
173 |                 const hasToolCalls = await this.handleToolCalls(llmResponse, spinner);
174 |                 
175 |                 if (!hasToolCalls) {
176 |                     // 最终文本响应
177 |                     const finalResponse: AgentResponse = {
178 |                         content: llmResponse?.content ?? '',
179 |                         role: 'assistant',
180 |                         type: 'text',
181 |                     };
182 | 
183 |                     spinner.succeed(finalResponse.content);
184 |                     return finalResponse;
185 |                 }
186 | 
187 |                 // 工具调用成功，重置连续错误计数
188 |                 consecutiveErrorCount = 0;
189 | 
190 |             } catch (error) {
191 |                 const errorMsg = error instanceof Error ? error.message : String(error);
192 |                 spinner.fail(errorMsg);
193 |                 this.logger.error(`LLM call failed: ${errorMsg}`);
194 | 
195 |                 this.sessionManager.addMessage({
196 |                     role: 'assistant',
197 |                     type: 'text',
198 |                     content: `LLM error: ${errorMsg}`,
199 |                 });
200 | 
201 |                 consecutiveErrorCount++;
202 | 
203 |                 if (consecutiveErrorCount > this.noProgressLimit) {
204 |                     return {
205 |                         content: `Max error limit reached: ${errorMsg}`,
206 |                         role: 'assistant',
207 |                     };
208 |                 }
209 |             }
210 |         }
211 | 
212 |         // Bug修复：循环达到上限时返回错误信息
213 |         return {
214 |             content: 'Error :Agent reached maximum loop limit without completion',
215 |             role: 'assistant',
216 |         };
217 |     }
218 | }
219 |

--- FILE: ./src/tool/registry.ts ---
Range: 1 - 320

1 | import { BaseTool, ToolOutput } from "./base";
2 | 
3 | /**
4 |  * 工具注册表类
5 |  *
6 |  * 单例模式，管理所有可用的工具
7 |  */
8 | export class ToolRegistry {
9 |     /** 已注册的工具映射 */
10 |     private static tools: Map<string, BaseTool<any>> = new Map();
11 |     private static context: { sessionId?: string; sessionPath?: string; allowedTools?: string[] } = {};
12 | 
13 |     /** 私有构造函数，防止外部实例化 */
14 |     private constructor() {}
15 | 
16 |     /**
17 |      * 注册工具
18 |      *
19 |      * 支持单个工具或工具数组
20 |      *
21 |      * @param tool - 工具实例或工具数组
22 |      * @throws 如果工具名称已存在
23 |      *
24 |      * @example
25 |      * ```ts
26 |      * // 注册单个工具
27 |      * ToolRegistry.register(new BashTool());
28 |      *
29 |      * // 批量注册工具
30 |      * ToolRegistry.register([new BashTool(), new GrepTool()]);
31 |      * ```
32 |      */
33 |     static register<T extends BaseTool<any>>(tool: T | T[]): void {
34 |         const tools = Array.isArray(tool) ? tool : [tool];
35 |         for (const t of tools) {
36 |             if (this.tools.has(t.name)) {
37 |                 throw new Error(`Tool "${t.name}" is already registered`);
38 |             }
39 |             this.tools.set(t.name, t);
40 |         }
41 |     }
42 | 
43 |     /**
44 |      * 注销工具
45 |      *
46 |      * @param name - 工具名称
47 |      * @returns 是否成功注销
48 |      */
49 |     static unregister(name: string): boolean {
50 |         return this.tools.delete(name);
51 |     }
52 | 
53 |     /**
54 |      * 根据名称获取工具
55 |      *
56 |      * @param name - 工具名称
57 |      * @returns 工具实例，如果不存在则返回 undefined
58 |      */
59 |     static get<T extends BaseTool<any> = BaseTool<any>>(name: string): T | undefined {
60 |         return this.tools.get(name) as T | undefined;
61 |     }
62 | 
63 |     /**
64 |      * 获取所有已注册的工具
65 |      *
66 |      * @returns 工具实例数组
67 |      */
68 |     static getAll(): BaseTool<any>[] {
69 |         return Array.from(this.tools.values());
70 |     }
71 | 
72 |     /**
73 |      * 获取所有工具的名称
74 |      *
75 |      * @returns 工具名称数组
76 |      */
77 |     static getNames(): string[] {
78 |         return Array.from(this.tools.keys());
79 |     }
80 | 
81 |     /**
82 |      * 检查工具是否已注册
83 |      *
84 |      * @param name - 工具名称
85 |      * @returns 是否已注册
86 |      */
87 |     static has(name: string): boolean {
88 |         return this.tools.has(name);
89 |     }
90 | 
91 |     /**
92 |      * 获取已注册工具的数量
93 |      *
94 |      * @returns 工具数量
95 |      */
96 |     static get size(): number {
97 |         return this.tools.size;
98 |     }
99 | 
100 |     /**
101 |      * 清空所有已注册的工具
102 |      *
103 |      * @warning 这通常只在测试中使用
104 |      */
105 |     static clear(): void {
106 |         this.tools.clear();
107 |     }
108 | 
109 |     static setContext(context: { sessionId?: string; sessionPath?: string; allowedTools?: string[] }): void {
110 |         const next = { ...this.context, ...context };
111 |         if ('allowedTools' in context && context.allowedTools === undefined) {
112 |             delete (next as any).allowedTools;
113 |         }
114 |         this.context = next;
115 |     }
116 | 
117 |     static getContext(): { sessionId?: string; sessionPath?: string; allowedTools?: string[] } {
118 |         return this.context;
119 |     }
120 | 
121 |     /**
122 |      * 执行指定工具
123 |      *
124 |      * @param name - 工具名称
125 |      * @param args - 工具参数
126 |      * @returns 执行结果
127 |      * @throws 如果工具不存在或参数无效
128 |      */
129 |     static async execute(name: string, args: string): Promise<ToolOutput> {
130 |         const tool = this.get(name);
131 | 
132 |         if (!tool) {
133 |             return `Tool "${name}" not found`;
134 |         }
135 | 
136 |         const allowed = this.context.allowedTools;
137 |         if (allowed && !allowed.includes(name)) {
138 |             return `Tool "${name}" is not allowed in this context`;
139 |         }
140 |         
141 |         
142 |         
143 |       try {   
144 |         const argsObj = JSON.parse(args);
145 |         
146 |         // 验证参数
147 |         const parsed = tool.schema.safeParse(argsObj);
148 |        
149 |         if (!parsed.success) {
150 |              throw new Error(`Invalid arguments  ${parsed.error.errors.map((e: { message: string }) => e.message).join(', ')}`);
151 |         }
152 |         
153 | 
154 |          return await tool.execute(parsed.data);
155 |          
156 |         } catch (error) {
157 |             return `Error executing tool "${name}": ${error instanceof Error ? error.message : String(error)}`;
158 |         }
159 |     }
160 | 
161 | 
162 |     /**
163 |      * 获取工具的 schema（用于 LLM 函数调用）
164 |      *
165 |      * 返回符合 OpenAI function calling 格式：
166 |      * https://platform.openai.com/docs/guides/function-calling
167 |      *
168 |      * @returns 所有工具的 schema 数组
169 |      */
170 |     static getSchemas(): Array<{
171 |         type: 'function';
172 |         function: {
173 |             name: string;
174 |             description: string;
175 |             strict?: boolean;
176 |             parameters: Record<string, unknown>;
177 |         };
178 |     }> {
179 |         return this.getAll().map(tool => {
180 |             // 将 zod schema 转换为 JSON Schema 格式
181 |             const zodSchema = tool.schema;
182 |             const jsonSchema = this.zodToJsonSchema(zodSchema);
183 | 
184 |             return {
185 |                 type: 'function',
186 |                 function: {
187 |                     name: tool.name,
188 |                     description: tool.description,
189 |                     strict: true,
190 |                     parameters: jsonSchema,
191 |                 },
192 |             };
193 |         });
194 |     }
195 | 
196 |     /**
197 |      * 将 Zod schema 转换为 JSON Schema 格式
198 |      *
199 |      * @param schema - Zod schema
200 |      * @returns JSON Schema 对象
201 |      */
202 |     private static zodToJsonSchema(schema: any): Record<string, unknown> {
203 |         // 基础实现，处理常见类型
204 |         if (schema._def?.typeName === 'ZodObject') {
205 |             const shape = schema._def.shape();
206 |             const properties: Record<string, unknown> = {};
207 |             const required: string[] = [];
208 | 
209 |             for (const [key, value] of Object.entries(shape)) {
210 |                 const def = (value as any)._def;
211 |                 properties[key] = this.zodTypeToJsonSchema(def, key);
212 | 
213 |                 // 检查是否是可选字段
214 |                 const isOptional = (value as any)._def?.typeName === 'ZodOptional' ||
215 |                                    (value as any).isOptional?.();
216 |                 if (!isOptional) {
217 |                     required.push(key);
218 |                 }
219 |             }
220 | 
221 |             return {
222 |                 type: 'object',
223 |                 properties,
224 |                 required: required.length > 0 ? required : undefined,
225 |                 additionalProperties: false,
226 |             };
227 |         }
228 | 
229 |         return { type: 'object', properties: {}, additionalProperties: false };
230 |     }
231 | 
232 |     /**
233 |      * 将 Zod 类型转换为 JSON Schema 类型
234 |      *
235 |      * @param def - Zod 类型定义
236 |      * @param key - 字段名（用于错误信息）
237 |      * @returns JSON Schema 类型定义
238 |      */
239 |     private static zodTypeToJsonSchema(def: any, key?: string): Record<string, unknown> {
240 |         const typeName = def?.typeName;
241 | 
242 |         switch (typeName) {
243 |             case 'ZodString':
244 |                 return { type: 'string' };
245 | 
246 |             case 'ZodNumber':
247 |                 return { type: 'number' };
248 | 
249 |             case 'ZodBoolean':
250 |                 return { type: 'boolean' };
251 | 
252 |             case 'ZodNull':
253 |                 return { type: 'null' };
254 | 
255 |             case 'ZodArray':
256 |                 const itemType = this.zodTypeToJsonSchema(def.type?._def || def.type, key);
257 |                 return {
258 |                     type: 'array',
259 |                     items: itemType,
260 |                 };
261 | 
262 |             case 'ZodObject':
263 |                 return this.zodToJsonSchema({ _def: def });
264 | 
265 |             case 'ZodOptional':
266 |             case 'ZodNullable':
267 |             case 'ZodDefault':
268 |                 // innerType 是 Zod 对象，需要获取其 _def
269 |                 const wrappedType = def.innerType || def.schema || def.type;
270 |                 if (!wrappedType) {
271 |                     console.warn(`Missing wrapped type for field: ${key}, def:`, def);
272 |                     return {};
273 |                 }
274 |                 return this.zodTypeToJsonSchema(wrappedType._def || wrappedType, key);
275 | 
276 |             case 'ZodEnum':
277 |                 return {
278 |                     type: 'string',
279 |                     enum: def.values,
280 |                 };
281 | 
282 |             case 'ZodLiteral':
283 |                 return {
284 |                     type: typeof def.value,
285 |                     const: def.value,
286 |                 };
287 | 
288 |             case 'ZodUnion':
289 |             case 'ZodDiscriminatedUnion':
290 |                 return {
291 |                     anyOf: def.options?.map((opt: any) => this.zodTypeToJsonSchema(opt._def || opt)),
292 |                 };
293 | 
294 |             case 'ZodEffects':
295 |                 // 处理带描述的字段
296 |                 const effectType = def.innerType || def.schema || def.type;
297 |                 if (!effectType) {
298 |                     console.warn(`Missing effect inner type for field: ${key}, def:`, def);
299 |                     return {};
300 |                 }
301 |                 const innerSchema = this.zodTypeToJsonSchema(effectType._def || effectType, key);
302 |                 if (def.description) {
303 |                     return { ...innerSchema, description: def.description };
304 |                 }
305 |                 return innerSchema;
306 | 
307 |             default:
308 |                 // 未知类型，使用 any
309 |                 if (typeName !== undefined) {
310 |                     console.warn(`Unknown Zod type: ${typeName} for field: ${key}`);
311 |                 } else {
312 |                     console.warn(`Undefined Zod type definition for field: ${key}, def:`, def);
313 |                 }
314 |                 return {};
315 |         }
316 |     }
317 | 
318 | 
319 | }
320 |

